using System;using System.IO;using System.Linq;using System.Text;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using System.Windows.Threading;
namespace SeraphimLuxury {static class Design14Tests {
 public static int Scan(string file){var entries=InstalledCatalog14.Scan();File.WriteAllText(file,"PASS Windows registered catalogue: "+entries.Count+" entries, "+entries.Count(e=>File.Exists(e.Executable??e.Target))+" executable shortcuts, "+entries.Where(e=>e.Target.StartsWith("shell:AppsFolder")).Take(10).Count(e=>ShellImage14.Read(e.Target)!=null)+" / 10 shell icons.");return entries.Count>0?0:1;}
 public static int Assets(string root){var app=new Application();var w=new MainWindow(new PreferenceStore(Path.Combine(root,"source","asset-fixture.json")),true){Opacity=0,ShowInTaskbar=false};var entry=new AppEntry {Id="calculator",Name="Calculatrice",Target=Path.Combine(Environment.SystemDirectory,"calc.exe")};var icon=w.ApplicationLogo(entry,128);icon.Measure(new Size(128,128));icon.Arrange(new Rect(0,0,128,128));Branding.Capture(icon,Path.Combine(root,"assets","app-calculator.png"));w.Close();app.Shutdown();return 0;}
 static void Check(bool value,string message){if(!value)throw new Exception(message);}
 public static int Run(string dir){Directory.CreateDirectory(dir);var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var prefs=Preferences.Defaults();prefs.Premium=true;prefs.ReducedMotion=false;var plan=Planning.Get(prefs,DateTime.Today);plan.Tasks.Add(new PlanTask{Id="1",Title="Composer la scène",Time="10:30",Minutes=45});plan.Tasks.Add(new PlanTask{Id="2",Title="Tester les interactions",Time="14:00",Minutes=30});plan.Tasks.Add(new PlanTask{Id="3",Title="Relire le script",Time="16:30",Minutes=20});var store=new PreferenceStore(Path.Combine(dir,"preferences.json"));store.Save(prefs);var w=new MainWindow(store,true){Opacity=0,ShowInTaskbar=false};app.MainWindow=w;int stage=0,builds=0;ScrollViewer catalogue=null;var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(700)};timer.Tick+=delegate{try{switch(stage++){
 case 0:Check(ControlCatalog14.All.Count==8&&ControlCatalog14.All.Sum(d=>d.Rules.Count)==47,"Catalogue complet Control");w.Capture(Path.Combine(dir,"home.png"));w.ShowPage("Applications");builds=w.ApplicationPageBuilds14;catalogue=w.catalogScroll14;break;
 case 1:w.Capture(Path.Combine(dir,"applications.png"));var choose=ToolsTests.Descend(w.ToolsPage).OfType<Button>().First(b=>AutomationProperties.GetName(b)=="Choisir Instagram");choose.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(w.ApplicationPageBuilds14==builds&&Object.ReferenceEquals(catalogue,w.catalogScroll14),"Sélection locale sans rechargement");break;
 case 2:var masks=ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>().First(f=>AutomationProperties.GetName(f.Header)=="Masquage · Instagram");masks.SetOpen(true,false);w.UpdateLayout();Check(ToolsTests.Descend(masks).OfType<CheckBox>().Count()==ControlCatalog14.All.First(d=>d.Id=="instagram").Rules.Count+1,"Toutes les options Instagram sont affichées");w.Capture(Path.Combine(dir,"instagram.png"));var cb=ToolsTests.Descend(masks).OfType<CheckBox>().First(c=>AutomationProperties.GetName(c)=="Masquer les Reels");cb.IsChecked=true;var wire=w.BrowserRequest(new BridgeRequest {action="status"});Check(wire.policies.First(p=>p.Id=="instagram").Flags.First(f=>f.Key=="Reels").Value,"Réglage relié au pont natif");w.catalogSearch14.Text="calcul";Check(w.ApplicationPageBuilds14==builds&&Object.ReferenceEquals(catalogue,w.catalogScroll14),"Recherche sans rechargement");w.ShowPage("Planning");break;
 case 3:w.Capture(Path.Combine(dir,"planning.png"));Check(ToolsTests.Descend(w.ToolsPage).OfType<CheckBox>().Count()>=4,"Tâches modifiables et règles présentes");w.ShowPage("Checklist");foreach(var fold in ToolsTests.Descend(w.ToolsPage).OfType<RevealSection>())fold.SetOpen(true,false);break;
 case 4:w.Capture(Path.Combine(dir,"checklist.png"));w.ShowPage("Web");break;
 case 5:w.Capture(Path.Combine(dir,"web.png"));w.ShowPage("Applications");var horizontal=ToolsTests.Descend(w.ToolsPage).OfType<Button>().First(b=>AutomationProperties.GetName(b)=="Horizontal");horizontal.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));break;
 case 6:w.Capture(Path.Combine(dir,"applications-horizontal.png"));Check(w.catalogScroll14.HorizontalScrollBarVisibility==ScrollBarVisibility.Auto,"Disposition horizontale");w.Width=980;w.Height=680;w.ShowPage("Planning");break;
 case 7:w.Capture(Path.Combine(dir,"planning-minimum.png"));w.BeginLoading(false);break;
 case 8:w.Capture(Path.Combine(dir,"loading.png"));w.SampleCancel();timer.Stop();w.Close();File.WriteAllText(Path.Combine(dir,"design14-test.txt"),"PASS catalogue 8 plateformes / 47 options, sélection et recherche locales, pont de réglages, planning, checklist, compagnon, chargement et captures.");app.Shutdown();break;
 }}catch(Exception ex){timer.Stop();File.WriteAllText(Path.Combine(dir,"design14-test.txt"),"FAIL stage "+stage+" "+ex);w.SampleCancel();w.Close();app.Shutdown(1);}};w.Loaded+=delegate{timer.Start();};return app.Run(w);}
}}
